CREATE TABLE public.pend_links (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), token text NOT NULL UNIQUE DEFAULT encode(gen_random_bytes(32),'hex') CHECK(length(token)>=32), nome_cliente text NOT NULL, ativo boolean NOT NULL DEFAULT true, expira_em timestamptz, criado_em timestamptz NOT NULL DEFAULT now(), ultimo_acesso_em timestamptz);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.pend_links TO authenticated; GRANT ALL ON public.pend_links TO service_role;
ALTER TABLE public.pend_links ENABLE ROW LEVEL SECURITY;
CREATE POLICY pend_links_admin ON public.pend_links FOR ALL TO authenticated USING(public.nf_has_role(auth.uid(),'admin_goable')) WITH CHECK(public.nf_has_role(auth.uid(),'admin_goable'));
CREATE TABLE public.pend_itens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), link_id uuid NOT NULL REFERENCES public.pend_links(id), ordem integer NOT NULL DEFAULT 1, categoria text NOT NULL DEFAULT 'outros' CHECK(categoria IN ('fiscal','dados','envio','regras','operacao','outros')), prioridade text NOT NULL CHECK(prioridade IN ('bloqueia_producao','importante','desejavel')), titulo text NOT NULL, descricao text NOT NULL DEFAULT '', tipo text NOT NULL CHECK(tipo IN ('texto_curto','texto_longo','cnpj','email','telefone','data','sim_nao_naosei','escolha_unica','escolha_multipla','contato','arquivos','composto')), config jsonb NOT NULL DEFAULT '{}', obrigatoria boolean NOT NULL DEFAULT true, status text NOT NULL DEFAULT 'aberta' CHECK(status IN ('aberta','respondida','em_analise','precisa_complemento','resolvida')), comentario_goable text NOT NULL DEFAULT '', criado_em timestamptz NOT NULL DEFAULT now(), atualizado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.pend_itens TO authenticated; GRANT ALL ON public.pend_itens TO service_role;
ALTER TABLE public.pend_itens ENABLE ROW LEVEL SECURITY;
CREATE POLICY pend_itens_admin ON public.pend_itens FOR ALL TO authenticated USING(public.nf_has_role(auth.uid(),'admin_goable')) WITH CHECK(public.nf_has_role(auth.uid(),'admin_goable'));
CREATE INDEX pend_itens_link ON public.pend_itens(link_id,ordem);
CREATE TABLE public.pend_respostas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), item_id uuid NOT NULL UNIQUE REFERENCES public.pend_itens(id), valor jsonb NOT NULL, respondido_por_nome text NOT NULL, respondido_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.pend_respostas TO authenticated; GRANT ALL ON public.pend_respostas TO service_role;
ALTER TABLE public.pend_respostas ENABLE ROW LEVEL SECURITY;
CREATE POLICY pend_respostas_admin ON public.pend_respostas FOR ALL TO authenticated USING(public.nf_has_role(auth.uid(),'admin_goable')) WITH CHECK(public.nf_has_role(auth.uid(),'admin_goable'));
CREATE TABLE public.pend_respostas_hist (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), item_id uuid NOT NULL REFERENCES public.pend_itens(id), valor jsonb NOT NULL, respondido_por_nome text NOT NULL, respondido_em timestamptz NOT NULL, arquivado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.pend_respostas_hist TO authenticated; GRANT ALL ON public.pend_respostas_hist TO service_role;
ALTER TABLE public.pend_respostas_hist ENABLE ROW LEVEL SECURITY;
CREATE POLICY pend_hist_admin ON public.pend_respostas_hist FOR SELECT TO authenticated USING(public.nf_has_role(auth.uid(),'admin_goable'));
CREATE TABLE public.pend_arquivos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), item_id uuid NOT NULL REFERENCES public.pend_itens(id), campo_key text NOT NULL DEFAULT '', storage_path text NOT NULL UNIQUE, nome_original text NOT NULL, mime text NOT NULL, tamanho bigint NOT NULL CHECK(tamanho > 0 AND tamanho <= 26214400), enviado_por_nome text NOT NULL, enviado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.pend_arquivos TO authenticated; GRANT ALL ON public.pend_arquivos TO service_role;
ALTER TABLE public.pend_arquivos ENABLE ROW LEVEL SECURITY;
CREATE POLICY pend_arquivos_admin ON public.pend_arquivos FOR ALL TO authenticated USING(public.nf_has_role(auth.uid(),'admin_goable')) WITH CHECK(public.nf_has_role(auth.uid(),'admin_goable'));
CREATE INDEX pend_arquivos_item ON public.pend_arquivos(item_id);
CREATE INDEX pend_hist_item ON public.pend_respostas_hist(item_id,respondido_em);
CREATE FUNCTION public.pend_submit(_token text,_item uuid,_valor jsonb,_nome text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.pend_itens; BEGIN SELECT i.* INTO r FROM public.pend_itens i JOIN public.pend_links l ON l.id=i.link_id WHERE i.id=_item AND l.token=_token AND l.ativo AND (l.expira_em IS NULL OR l.expira_em>now()) FOR UPDATE OF i; IF r.id IS NULL THEN RAISE EXCEPTION 'Link inválido ou expirado'; END IF; IF r.status='resolvida' THEN RAISE EXCEPTION 'Item resolvido: somente leitura'; END IF; INSERT INTO public.pend_respostas_hist(item_id,valor,respondido_por_nome,respondido_em) SELECT item_id,valor,respondido_por_nome,respondido_em FROM public.pend_respostas WHERE item_id=_item; INSERT INTO public.pend_respostas(item_id,valor,respondido_por_nome) VALUES(_item,_valor,_nome) ON CONFLICT(item_id) DO UPDATE SET valor=excluded.valor,respondido_por_nome=excluded.respondido_por_nome,respondido_em=now(); UPDATE public.pend_itens SET status='respondida',atualizado_em=now() WHERE id=_item; END; $$;
REVOKE ALL ON FUNCTION public.pend_submit(text,uuid,jsonb,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.pend_submit(text,uuid,jsonb,text) TO service_role;
CREATE FUNCTION public.pend_register_file(_token text,_item uuid,_campo text,_path text,_nome text,_mime text,_tamanho bigint,_autor text,_max integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.pend_itens; n integer; result uuid; BEGIN SELECT i.* INTO r FROM public.pend_itens i JOIN public.pend_links l ON l.id=i.link_id WHERE i.id=_item AND l.token=_token AND l.ativo AND (l.expira_em IS NULL OR l.expira_em>now()) FOR UPDATE OF i; IF r.id IS NULL OR r.status='resolvida' THEN RAISE EXCEPTION 'Item indisponível'; END IF; SELECT count(*) INTO n FROM public.pend_arquivos WHERE item_id=_item AND campo_key=_campo; IF n>=_max THEN RAISE EXCEPTION 'Limite de arquivos atingido'; END IF; INSERT INTO public.pend_arquivos(item_id,campo_key,storage_path,nome_original,mime,tamanho,enviado_por_nome) VALUES(_item,_campo,_path,_nome,_mime,_tamanho,_autor) RETURNING id INTO result; RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.pend_register_file(text,uuid,text,text,text,text,bigint,text,integer) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.pend_register_file(text,uuid,text,text,text,text,bigint,text,integer) TO service_role;
CREATE POLICY pend_storage_admin_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='pendencias' AND public.nf_has_role(auth.uid(),'admin_goable'));